<script setup lang="ts">import{onMounted,ref}from"vue";import{IndustryAgentService,type IndustryRobot,type IndustrySkill}from"../../../../frontend/src/services/industry-agent-service";const s=new IndustryAgentService({requestId:crypto.randomUUID(),traceId:crypto.randomUUID(),identityId:"local-user",identityKind:"user",tenantId:"local-default"});const skills=ref<IndustrySkill[]>([]),robots=ref<IndustryRobot[]>([]),project=ref("default-project"),mode=ref("serial"),error=ref("");onMounted(async()=>skills.value=(await s.skills()).items);async function add(skill:IndustrySkill){try{robots.value.push(await s.robot(skill.skill_id,project.value))}catch(e){error.value=e instanceof Error?e.message:"失败"}}async function create(){try{await s.workflow({operation:"create",workflow_id:`workflow-${project.value}`,industry_id:skills.value[0]?.industry_id,robot_ids:robots.value.map(x=>x.robot_id),mode:mode.value})}catch(e){error.value=e instanceof Error?e.message:"失败"}}</script>
<template><section><strong>行业流程机器人</strong><div><input v-model="project" placeholder="项目 ID"><select v-model="mode"><option>serial</option><option>parallel</option><option>branching</option></select><button :disabled="!robots.length" @click="create">保存拓扑</button></div><button v-for="skill in skills" :key="skill.skill_id" @click="add(skill)">＋ {{skill.name}}</button><p v-for="robot in robots" :key="robot.robot_id">{{robot.name}} · {{robot.status}}</p><em>{{error}}</em></section></template>
